-- Local disposable fixture only. scripts/test-fb-sql-local.py wraps BEGIN/ROLLBACK.
create temporary table s53_checks(label text);
grant insert on s53_checks to authenticated,anon;
create function pg_temp.check(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; insert into s53_checks values(label); end $$;
create function pg_temp.expect_error(statement text,state text,label text) returns void language plpgsql as $$ begin
 begin execute statement; exception when others then if sqlstate=state then perform pg_temp.check(true,label); return; end if; raise exception 'FAIL %: expected %, got % %',label,state,sqlstate,sqlerrm; end;
 raise exception 'FAIL %: expected error %',label,state;
end $$;
select pg_temp.check(current_setting('fb_fixture.storage_unsafe_verified',true)='true','unsafe browser Storage policy blocks migration');
select pg_temp.check(current_setting('fb_fixture.storage_other_verified',true)='true','unrelated narrow Storage bucket remains compatible');
select pg_temp.check(current_setting('fb_fixture.storage_inherited_verified',true)='true','inherited role cannot bypass server-only Storage preflight');
create temporary table s53_context(hotel uuid,actor uuid,outlet uuid,other_outlet uuid,menu uuid,category uuid,item uuid,service uuid);
grant select on s53_context to authenticated,anon;
do $$ declare n integer; h uuid; actor uuid; service uuid; outlet jsonb; other_outlet jsonb; menu jsonb; category jsonb; item jsonb; projection jsonb; names text[]:=array['Grand Mercure Copacabana','Novotel Leme','Novotel Salvador Rio Vermelho','Mercure Rio Boutique Copacabana','Bugan Recife','Default técnico']; begin
 for n in 1..6 loop
 h:=('53000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;
 actor:=('53100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;
 service:=('53200000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;
 insert into public.hotels values(h,names[n],'active');insert into public.profiles values(actor,h,'operador',true);
 perform pg_temp.check(not public.is_hotel_module_enabled(h,'fb.menu'),names[n]||' no auto-enable');
 insert into public.hotel_module_entitlements(hotel_id,module_key,is_enabled) values(h,'core.directory',true),(h,'fb.menu',true),(h,'content.languages',true),(h,'content.services',true);
 perform pg_temp.check(jsonb_array_length(public.get_public_hotel_fb(h,'pt')->'outlets')=0,names[n]||' zero outlets');
 insert into public.hotel_sections values(service,h,case when n=5 then 'Room Service' else 'Fixture service' end,null,case when n=5 then 'https://hotel-bugan.goomer.app/menu' else 'https://example.invalid/menu' end,'external_url',true);
 perform set_config('request.jwt.claim.sub',actor::text,true);
 outlet:=public.save_current_hotel_fb('outlet',null,0,jsonb_build_object('name',case when n=5 then 'Restaurante Filipe' else 'Fixture restaurante' end,'type','restaurant','short_description','Fixture isolada','is_published',true,'action_type','service','service_id',service));
 perform pg_temp.check(jsonb_array_length(public.get_public_hotel_fb(h,'pt')->'outlets')=1,names[n]||' one outlet');
 menu:=public.save_current_hotel_fb('menu',null,0,'{"name":"Menu fixture","is_published":true}');
 category:=public.save_current_hotel_fb('category',null,0,jsonb_build_object('name','Categoria fixture','menu_id',menu->>'id','is_published',true));
 item:=public.save_current_hotel_fb('item',null,0,jsonb_build_object('name','Item fixture','category_id',category->>'id','price_amount_minor',2590,'allergens_info','Informação fornecida pelo hotel','is_published',true));
 outlet:=public.save_current_hotel_fb('outlet',(outlet->>'id')::uuid,1,jsonb_build_object('menu_ids',jsonb_build_array(menu->>'id')));
 other_outlet:=public.save_current_hotel_fb('outlet',null,0,jsonb_build_object('name','Room Service fixture','type','room_service','is_published',true,'menu_ids',jsonb_build_array(menu->>'id')));
 insert into s53_context values(h,actor,(outlet->>'id')::uuid,(other_outlet->>'id')::uuid,(menu->>'id')::uuid,(category->>'id')::uuid,(item->>'id')::uuid,service);
 projection:=public.get_public_hotel_fb(h,'pt');
 perform pg_temp.check(jsonb_array_length(projection->'outlets')=2,names[n]||' multiple outlets');
 perform pg_temp.check(jsonb_array_length(projection->'menus')=1 and jsonb_array_length(projection->'outlet_menus')=2,names[n]||' shared menu');
 perform pg_temp.check(jsonb_array_length(projection->'items')=1,names[n]||' published item');
 perform pg_temp.check(jsonb_array_length(projection->'service_links')=1,names[n]||' eligible service link');
 update public.hotel_module_entitlements set is_enabled=false where hotel_id=h and module_key='content.services';
 perform pg_temp.check(jsonb_array_length(public.get_public_hotel_fb(h,'pt')->'service_links')=0,names[n]||' services off hides link');
 update public.hotel_module_entitlements set is_enabled=true where hotel_id=h and module_key='content.services';
 update public.hotel_sections set enabled=false where id=service;
 perform pg_temp.check(jsonb_array_length(public.get_public_hotel_fb(h,'pt')->'service_links')=0,names[n]||' disabled service hides link');
 update public.hotel_sections set enabled=true where id=service;
 perform pg_temp.check(projection->'outlets'->0->>'created_at' is null,names[n]||' minimal projection');
 perform pg_temp.check(public.save_current_hotel_fb_translation('item',(item->>'id')::uuid,'en',1,'{"name":"Fixture item"}'),names[n]||' EN independent');
 perform pg_temp.check(public.save_current_hotel_fb_translation('item',(item->>'id')::uuid,'es',1,'{"name":"Artículo fixture"}'),names[n]||' ES independent');
 perform pg_temp.check(public.get_public_hotel_fb(h,'en')->'items'->0->>'name'='Fixture item',names[n]||' translation');
 perform pg_temp.check(public.get_public_hotel_fb(h,'en')->'items'->0->>'allergens_info'='Informação fornecida pelo hotel',names[n]||' per-field fallback');
 item:=public.save_current_hotel_fb('item',(item->>'id')::uuid,1,'{"name":"Item revisado"}');
 perform pg_temp.check(not public.save_current_hotel_fb_translation('item',(item->>'id')::uuid,'en',1,'{"name":"Stale"}'),names[n]||' stale is false');
 perform pg_temp.check(public.get_public_hotel_fb(h,'en')->'items'->0->>'name'='Item revisado',names[n]||' stale PT fallback');
 perform pg_temp.expect_error(format('select public.save_current_hotel_fb(''item'',%L,1,''{"name":"Overwritten"}'')',item->>'id'),'PT409',names[n]||' CAS');
 item:=public.save_current_hotel_fb('item',(item->>'id')::uuid,2,'{"is_available":false}');
 perform pg_temp.check(jsonb_array_length(public.get_public_hotel_fb(h,'pt')->'items')=0,names[n]||' unavailable hidden');
 perform public.save_current_hotel_fb('item',(item->>'id')::uuid,3,'{"is_available":true}');
 perform public.save_current_hotel_fb('menu',(menu->>'id')::uuid,1,'{"is_published":false}');
 perform pg_temp.check(jsonb_array_length(public.get_public_hotel_fb(h,'pt')->'items')=0,names[n]||' unpublished ancestor hidden');
 perform public.save_current_hotel_fb('menu',(menu->>'id')::uuid,2,'{"is_published":true}');
 update public.hotel_module_entitlements set is_enabled=false where hotel_id=h and module_key='content.languages';
 perform pg_temp.check(not public.save_current_hotel_fb_translation('item',(item->>'id')::uuid,'es',2,'{"name":"Not saved"}'),names[n]||' languages off');
 update public.hotel_module_entitlements set is_enabled=true where hotel_id=h and module_key='content.languages';
 update public.hotel_module_entitlements set is_enabled=false where hotel_id=h and module_key='fb.menu';
 perform pg_temp.check(public.get_public_hotel_fb(h,'pt') is null,names[n]||' module off legacy signal');
 perform pg_temp.expect_error('select public.save_current_hotel_fb(''menu'',null,0,''{"name":"Forbidden"}'')','42501',names[n]||' module off mutation');
 update public.hotel_module_entitlements set is_enabled=true where hotel_id=h and module_key='fb.menu';
 update public.profiles set role='visualizador' where id=actor;
 perform pg_temp.expect_error('select public.save_current_hotel_fb(''menu'',null,0,''{"name":"Forbidden"}'')','42501',names[n]||' viewer no write');
 update public.profiles set role='operador' where id=actor;
 update public.hotels set platform_status='archived' where id=h;
 perform pg_temp.check(public.get_public_hotel_fb(h,'pt') is null,names[n]||' archived hidden');
 perform pg_temp.expect_error('select public.save_current_hotel_fb(''menu'',null,0,''{"name":"Forbidden"}'')','42501',names[n]||' archived no write');
 update public.hotels set platform_status='active' where id=h;
 end loop;
end $$;
do $$ declare current_h uuid; foreign_menu uuid; foreign_service uuid; item_id uuid; r integer; source integer; ordered jsonb; output jsonb; before_count integer; begin
 select hotel,item into current_h,item_id from s53_context order by hotel desc limit 1;
 select menu,service into foreign_menu,foreign_service from s53_context order by hotel limit 1;
 perform pg_temp.expect_error(format('select public.save_current_hotel_fb(''category'',null,0,jsonb_build_object(''name'',''Forbidden'',''menu_id'',%L))',foreign_menu),'23503','cross-tenant menu FK');
 perform pg_temp.expect_error(format('select public.save_current_hotel_fb(''item'',null,0,jsonb_build_object(''name'',''Forbidden'',''category_id'',%L))',(select category from s53_context order by hotel limit 1)),'23503','cross-tenant category FK');
 perform pg_temp.expect_error(format('update public.hotel_sections set hotel_id=%L where id=%L',current_h,foreign_service),'23503','service cannot change tenant with linked outlet');
 perform pg_temp.expect_error(format('select public.save_current_hotel_fb(''outlet'',null,0,jsonb_build_object(''name'',''Forbidden'',''action_type'',''service'',''service_id'',%L))',foreign_service),'23503','cross-tenant service');
 perform pg_temp.expect_error('select public.save_current_hotel_fb(''menu'',null,0,''{"name":"x","hotel_id":"53000000-0000-4000-8000-000000000001"}'')','22023','browser hotel rejected');
 perform pg_temp.expect_error('select public.save_current_hotel_fb(''menu'',null,0,''{"name":"<script>"}'')','22023','plain text');
 perform pg_temp.expect_error('select public.save_current_hotel_fb(''outlet'',null,0,''{"name":"x","type":"arbitrary"}'')','23514','controlled outlet type');
 perform pg_temp.expect_error('select public.save_current_hotel_fb(''outlet'',null,0,''{"name":"x","action_type":"external_url","external_url":"https://user:password@example.invalid/"}'')','23514','URL credentials');
 perform pg_temp.expect_error(format('select public.save_current_hotel_fb(''item'',%L,4,''{"price_amount_minor":1200,"price_on_request":true}'')',item_id),'23514','price consistency');
 perform public.save_current_hotel_fb('item',item_id,4,'{"price_amount_minor":null,"price_on_request":true}');
 perform pg_temp.check(public.get_public_hotel_fb(current_h,'pt')->'items'->0->>'price_amount_minor' is null,'on request without amount');
 select jsonb_agg(jsonb_build_object('id',id,'revision',revision) order by sort_order desc,id) into ordered from public.hotel_fb_outlets where hotel_id=current_h;
 perform public.reorder_current_hotel_fb('outlet',null,ordered);
 perform pg_temp.check((select min(sort_order)=0 and max(sort_order)=1 from public.hotel_fb_outlets where hotel_id=current_h),'reorder contiguous');
 perform pg_temp.expect_error(format('select public.reorder_current_hotel_fb(''outlet'',null,%L)',ordered),'PT409','stale reorder');
 perform pg_temp.expect_error(format('select public.reorder_current_hotel_fb(''outlet'',null,%L)',jsonb_build_array(ordered->0,ordered->0)),'PT409','duplicate reorder');
 select revision,source_revision into r,source from public.hotel_fb_items where id=item_id;
 perform pg_temp.expect_error(format('select public.set_current_hotel_fb_image(''item'',%L,%s,''53000000-0000-4000-8000-000000000001/fb/item/invalid/x.png'')',item_id,r),'23514','foreign image ownership');
 perform pg_temp.expect_error(format('select public.set_current_hotel_fb_image(''item'',%L,%s,%L)',item_id,r,current_h::text||'/fb/item/'||item_id::text||'/53300000-0000-4000-8000-000000000001.png'),'23514','invented owned image path rejected');
 insert into storage.objects(bucket_id,name,metadata) values('hotel-assets',current_h::text||'/fb/item/'||item_id::text||'/53300000-0000-4000-8000-000000000001.png','{"mimetype":"image/png","size":500}');
 perform public.set_current_hotel_fb_image('item',item_id,r,current_h::text||'/fb/item/'||item_id::text||'/53300000-0000-4000-8000-000000000001.png');
 perform pg_temp.expect_error(format('select public.set_current_hotel_fb_image(''item'',%L,%s,%L)',item_id,r+1,current_h::text||'/fb/item/'||item_id::text||'/53300000-0000-4000-8000-000000000001.png'),'23514','previously associated object cannot be reattached during cleanup');
 perform pg_temp.check((select source_revision=source and revision=r+1 from public.hotel_fb_items where id=item_id),'image keeps source revision');
 perform pg_temp.check(exists(select 1 from public.admin_audit_log where hotel_id=current_h and action='fb.image_updated'),'image audit');
 output:=public.delete_current_hotel_fb('category',(select category from s53_context where hotel=current_h),1);
 perform pg_temp.check(not exists(select 1 from public.hotel_fb_items where id=item_id),'delete cascade items');
 perform pg_temp.check(not exists(select 1 from public.hotel_fb_items_translations where entity_id=item_id),'delete cascade translations');
 perform pg_temp.check(jsonb_array_length(output->'images')=1,'cascade cleanup manifest');
 perform pg_temp.check((select url='https://hotel-bugan.goomer.app/menu' from public.hotel_sections where hotel_id='53000000-0000-4000-8000-000000000005'),'Goomer preserved');
 perform pg_temp.check(not has_table_privilege('anon','public.hotel_fb_outlets','SELECT'),'anonymous projection only');
 perform pg_temp.check(not has_table_privilege('authenticated','public.hotel_fb_items','UPDATE'),'RPC-only DML');
 perform pg_temp.check(not has_function_privilege('service_role','public.save_current_hotel_fb(text,uuid,integer,jsonb)','EXECUTE'),'no service_role mutation bypass');
end $$;
update public.profiles set role='visualizador' where id='53100000-0000-4000-8000-000000000006';
set local role authenticated;
select pg_temp.check((select count(*)=2 from public.hotel_fb_outlets),'authenticated own tenant only');
select pg_temp.expect_error('insert into public.hotel_fb_menus(hotel_id,name) values(''53000000-0000-4000-8000-000000000006'',''Bypass'')','42501','direct insert denied');
select pg_temp.expect_error('update public.hotel_fb_outlets set is_published=true','42501','direct publish denied');
select pg_temp.expect_error('insert into storage.objects(bucket_id,name) values(''hotel-assets'',''53000000-0000-4000-8000-000000000006/fb/outlet/untrusted.png'')','42501','browser cannot bypass upload validation');
reset role;
update public.profiles set role='operador' where id='53100000-0000-4000-8000-000000000006';
create function pg_temp.reject_audit() returns trigger language plpgsql as $$ begin raise exception 'fixture audit failure'; end $$;
create trigger s53_audit_failure before insert on public.admin_audit_log for each row execute function pg_temp.reject_audit();
select pg_temp.expect_error('select public.save_current_hotel_fb(''menu'',null,0,''{"name":"Must rollback"}'')','P0001','audit failure atomic');
select pg_temp.check(not exists(select 1 from public.hotel_fb_menus where name='Must rollback'),'content rolled back with audit');
drop trigger s53_audit_failure on public.admin_audit_log;
set local role anon;
select pg_temp.check(public.get_public_hotel_fb('53000000-0000-4000-8000-000000000005','pt')->'outlets'->0->>'hotel_id'='53000000-0000-4000-8000-000000000005','anon scoped projection');
select pg_temp.expect_error('select * from public.hotel_fb_service_links','42501','anonymous no raw links');
reset role;
-- Only the active Platform Admin can opt in; future integrations remain blocked.
select public.save_current_hotel_fb('outlet',null,0,jsonb_build_object('name','Canal compartilhado fixture','action_type','service','service_id',(select service from s53_context order by hotel desc limit 1)));
select pg_temp.check((select count(*)=2 from public.hotel_fb_service_links where service_id=(select service from s53_context order by hotel desc limit 1)),'multiple outlets reuse one configured Service channel');
select pg_temp.check((select count(*)=1 from public.hotel_sections where hotel_id='53000000-0000-4000-8000-000000000006'),'shared Service channel creates no duplicate legacy record');
select pg_temp.expect_error('select public.update_platform_hotel_module(''53000000-0000-4000-8000-000000000006'',''fb.menu'',false)','42501','hotel operator cannot change entitlement');
insert into public.platform_users values('53900000-0000-4000-8000-000000000001','platform_admin',true);
select set_config('request.jwt.claim.sub','53900000-0000-4000-8000-000000000001',true);
do $$ declare before_other text; after_other text; begin
 select md5(string_agg(to_jsonb(e)::text,',' order by hotel_id,module_key)) into before_other from public.hotel_module_entitlements e where hotel_id<>'53000000-0000-4000-8000-000000000006';
 perform public.update_platform_hotel_module('53000000-0000-4000-8000-000000000006','fb.menu',false);
 perform pg_temp.check(public.get_public_hotel_fb('53000000-0000-4000-8000-000000000006','pt') is null,'Platform disable');
 perform public.update_platform_hotel_module('53000000-0000-4000-8000-000000000006','fb.menu',true);
 perform pg_temp.check(public.get_public_hotel_fb('53000000-0000-4000-8000-000000000006','pt') is not null,'Platform explicit opt-in');
 select md5(string_agg(to_jsonb(e)::text,',' order by hotel_id,module_key)) into after_other from public.hotel_module_entitlements e where hotel_id<>'53000000-0000-4000-8000-000000000006';
 perform pg_temp.check(before_other=after_other,'other five tenants unchanged by opt-in');
 perform pg_temp.check((select count(*)=2 from public.platform_audit_log where metadata->>'module_key'='fb.menu'),'entitlement atomic audit');
 perform pg_temp.expect_error('select public.update_platform_hotel_module(''53000000-0000-4000-8000-000000000006'',''integrations.thex'',true)','55000','TheX unavailable');
 perform pg_temp.expect_error('select public.update_platform_hotel_module(''53000000-0000-4000-8000-000000000006'',''integrations.opera'',true)','55000','OPERA unavailable');
 perform pg_temp.check(not has_function_privilege('anon','public.update_platform_hotel_module(uuid,text,boolean)','EXECUTE'),'anon no governance');
 perform pg_temp.check(not has_function_privilege('service_role','public.update_platform_hotel_module(uuid,text,boolean)','EXECUTE'),'service_role no governance');
end $$;
select jsonb_build_object('suite','53_fb_behavioral_matrix','passed',count(*),'failed',0,'tenants',6,'rollback',true) as result from s53_checks;
